def meses_para_meta(capital: float, taxa: float, meta: float) -> int:
    if capital >= meta:
        return 0
    if taxa <= 0:
        raise ValueError('com taxa não positiva a meta nunca é atingida')
    meses = 0
    while capital < meta:
        capital *= 1 + taxa
        meses += 1
    return meses


