from functools import wraps


def tentar(vezes: int):
    def decorator(funcao):
        @wraps(funcao)
        def envoltorio(*args, **kwargs):
            for tentativa in range(1, vezes + 1):
                try:
                    return funcao(*args, **kwargs)
                except ConnectionError:
                    if tentativa == vezes:
                        raise
        return envoltorio
    return decorator


