REGISTRO = {}


def plugin(nome: str):
    def registrar(funcao):
        REGISTRO[nome] = funcao
        return funcao
    return registrar


def executar(nome: str, *args):
    try:
        funcao = REGISTRO[nome]
    except KeyError:
        disponiveis = ', '.join(sorted(REGISTRO))
        raise LookupError(f'plugin {nome!r} não existe; disponíveis: {disponiveis}') from None
    return funcao(*args)


