from dataclasses import dataclass


@dataclass
class Item:
    nome: str
    preco: float
    qtd: int = 1

    def __post_init__(self) -> None:
        if self.qtd < 1:
            raise ValueError('quantidade deve ser pelo menos 1')

    @property
    def subtotal(self) -> float:
        return self.preco * self.qtd


class Carrinho:
    def __init__(self) -> None:
        self._itens: dict[str, Item] = {}

    def adicionar(self, item: Item) -> None:
        if item.nome in self._itens:
            self._itens[item.nome].qtd += item.qtd
        else:
            self._itens[item.nome] = item

    def total(self) -> float:
        return sum(i.subtotal for i in self._itens.values())

    def __len__(self) -> int:
        return len(self._itens)

    def __contains__(self, nome: str) -> bool:
        return nome in self._itens


c = Carrinho()
c.adicionar(Item('café', 18.9, 2))
print(len(c), c.total())

