from abc import ABC, abstractmethod


class Funcionario(ABC):
    def __init__(self, nome: str, salario_base: float):
        self.nome, self.salario_base = nome, salario_base

    @abstractmethod
    def salario(self) -> float: ...

    def __str__(self) -> str:
        return f'{self.nome}: R$ {self.salario():.2f}'


class Efetivo(Funcionario):
    def salario(self) -> float:
        return self.salario_base * 1.10


class Comissionado(Funcionario):
    def __init__(self, nome: str, salario_base: float, vendas: float):
        super().__init__(nome, salario_base)
        self.vendas = vendas

    def salario(self) -> float:
        return self.salario_base + self.vendas * 0.05


def folha(funcionarios) -> float:
    return round(sum(f.salario() for f in funcionarios), 2)


